"""Regenerates src/icon-photos.js from public/icons/*.png (base64 + natural
pixel size for each). Run after scripts/crop-icon-photos.py produces/updates
any PNGs. See src/icons.js's photoIcon()/ICON_PHOTOS for the consumer side.
"""

import base64
import os
from PIL import Image

REPO = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
ICONS_DIR = os.path.join(REPO, "public", "icons")
OUT_FILE = os.path.join(REPO, "src", "icon-photos.js")

names = sorted(
    n[:-4] for n in os.listdir(ICONS_DIR) if n.lower().endswith(".png")
)

lines = [
    "// AUTO-GENERATED by scripts/gen-icon-photos-module.py -- do not hand-edit.",
    "// Regenerate after scripts/crop-icon-photos.py adds/changes a PNG in",
    "// public/icons/. Source images: icon_refs/ phonics flashcard sheets",
    "// (user-licensed, free to crop/use as-is, see src/icons.js's",
    "// PHOTO-CROP ROUND comment for the mechanism this feeds).",
    "export const ICON_PHOTOS = {",
]
for n in names:
    path = os.path.join(ICONS_DIR, f"{n}.png")
    with open(path, "rb") as f:
        b64 = base64.b64encode(f.read()).decode("ascii")
    w, h = Image.open(path).size
    lines.append(f'  {n}: {{ w: {w}, h: {h}, data: "{b64}" }},')
lines.append("}")

with open(OUT_FILE, "w") as f:
    f.write("\n".join(lines) + "\n")

print(f"wrote {OUT_FILE} with {len(names)} entries")
